{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        { "speaker": "you", "text": "I'm vegan." },
        { "speaker": "partner", "text": "What does that mean?" },
        { "speaker": "you", "text": "I don't eat meat, fish, eggs, or dairy." },
        { "speaker": "you", "text": "I don't eat any animal products at all.", "or": true },
        { "speaker": "partner", "text": "Does that include dashi broth?" },
        { "speaker": "you", "text": "Yes, I can't have fish broth." },
        { "speaker": "partner", "text": "Understood." }
      ]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        { "speaker": "you", "text": "Does this have any meat in it?" },
        { "speaker": "partner", "text": "Yes, it has pork." },
        { "speaker": "partner", "text": "No, it's meatless.", "or": true },
        { "speaker": "you", "text": "Does it have dashi or fish broth?" },
        { "speaker": "partner", "text": "Yes, the soup uses fish broth." },
        { "speaker": "partner", "text": "No, it's plant-based broth.", "or": true },
        { "speaker": "you", "text": "Does it contain honey or eggs?" },
        { "speaker": "partner", "text": "It has eggs." },
        { "speaker": "partner", "text": "No, it's completely vegan.", "or": true }
      ]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        { "speaker": "you", "text": "I'll take the vegetable stir-fry." },
        { "speaker": "partner", "text": "Would you like rice with that?" },
        { "speaker": "you", "text": "Yes, please." },
        { "speaker": "you", "text": "No, just the stir-fry, please.", "or": true },
        { "speaker": "partner", "text": "Can I get you anything to drink?" },
        { "speaker": "you", "text": "Just water, please." },
        { "speaker": "partner", "text": "Coming right up." }
      ]
    }
  ]
}
